  "about_items": [
    {
      "n": "#497·31",
      "text": "A soft ribbed beanie in warm chocolate brown sits snugly on your head, framing your face gently without hiding it. Its fine knit texture adds comfort for frosty nights while keeping the look relaxed yet polished."
    },
    {
      "n": "#45·28",
      "text": "A cozy striped sweater with horizontal bands of cream and deep brown offers a casual-but-chic layer that complements your skin tone. The slightly cropped fit keeps the silhouette balanced without overwhelming your frame."
    },
    {
      "n": "#427·15",
      "text": "Milky ivory ankle boots with a low block heel and side zippers offer sleek lines and quiet elegance—they glide over winter floors without compromising comfort or style."
    },
    {
      "n": "#260·31",
      "text": "A relaxed midi dress in rich chocolate suede features subtle decorative seams that add structure to the silhouette. Its flowing shape drapes softly around your waist and hips, creating a graceful vertical line."
    },
    {
      "n": "#132·29",
      "text": "A sleek violet shoulder bag with a slender strap and metallic logo brings a touch of playful contrast to the earthy tones. Its smooth leather finish catches the light subtly as you move through the restaurant."
    },
    {
      "n": "#228·00",
      "text": "An oversized black fuzzy cardigan draped open acts as your warm, understated outer layer. Its long silhouette extends past your hips, adding height and drama without hiding your figure or interrupting the outfit’s flow."
    }
  ]
}
